/**
 * Ultra-optimized BPE tokenizer
 *
 * Optimizations applied:
 * - Pre-compiled regex patterns
 * - Shared TextEncoder/TextDecoder
 * - String-based encoding (no byte conversion for UTF-8)
 * - Binary search for non-UTF-8 tokens
 * - LRU merge cache for repeated encodings
 * - Sentinel values for branch elimination
 * - Cache-friendly rank updates
 * - Minimal allocations in hot paths
 * - ASCII fast path
 */

/**
 * Encoding data format (optimized)
 */
export interface Encoding {
  name: string;
  pat_str: string;
  special_tokens: Record<string, number>;
  stringEncoder: Record<string, number>;
  binaryEncoder: Array<[Uint8Array, number]>;
  decoder: Record<number, string | Uint8Array>;
}

/**
 * Ultra-optimized tokenizer for BPE encodings
 */
export default class Tokenizer {
  private readonly name: string;
  private readonly patternRegex: RegExp;
  private readonly specialTokensRegex: RegExp | null;
  private readonly specialTokens: Record<string, number>;
  private readonly inverseSpecialTokens: Record<number, Uint8Array>;

  // Optimized dual storage (pre-built at generation time)
  private readonly stringRankEncoder: Record<string, number>;
  private readonly binaryRankEncoder: Array<[Uint8Array, number]>;
  private readonly decoder: Record<number, string | Uint8Array>;
  private readonly binaryFirstByteIndex: Array<Array<
    [Uint8Array, number]
  > | null>;

  private readonly specialTokenKeys: readonly string[];
  private readonly hasSpecialTokens: boolean;

  // Simple piece-level cache
  private readonly mergeCache: Map<string, number[]>;
  private readonly mergeCacheSize: number;
  // Insertion-ordered ring of cached keys for O(1) FIFO eviction.
  // Map#keys().next() is O(holes) in V8 once entries have been deleted.
  private readonly mergeCacheKeys: string[];
  private mergeCacheHead = 0;

  constructor(
    data: Encoding,
    extendedSpecialTokens?: Record<string, number>,
    mergeCacheSize: number = 100000
  ) {
    this.name = data.name;
    this.mergeCacheSize = mergeCacheSize;
    this.mergeCache = new Map();
    this.mergeCacheKeys = [];

    // Use pre-optimized storage directly (zero-cost initialization)
    this.stringRankEncoder = data.stringEncoder;
    this.binaryRankEncoder = data.binaryEncoder;
    this.decoder = data.decoder;
    // Build first-byte index to reduce binary search domain size
    const idx: Array<Array<[Uint8Array, number]> | null> = new Array(256).fill(
      null
    );
    for (let i = 0; i < this.binaryRankEncoder.length; i++) {
      const entry = this.binaryRankEncoder[i]!;
      const arr = entry[0];
      if (arr.length === 0) continue;
      const first = arr[0]!;
      let bucket = idx[first]!;
      if (bucket === null) {
        bucket = [];
        idx[first] = bucket;
      }
      bucket.push(entry);
    }
    this.binaryFirstByteIndex = idx;

    // Pre-compile pattern regex
    this.patternRegex = new RegExp(data.pat_str, "ug");

    // Handle special tokens
    this.specialTokens = { ...data.special_tokens, ...extendedSpecialTokens };
    this.specialTokenKeys = Object.keys(this.specialTokens);
    this.hasSpecialTokens = this.specialTokenKeys.length > 0;

    // Pre-compile special tokens regex (only if needed)
    this.specialTokensRegex = this.hasSpecialTokens
      ? new RegExp(this.specialTokenKeys.map(escapeRegex).join("|"), "g")
      : null;

    // Pre-encode special tokens to Uint8Array
    this.inverseSpecialTokens = {};
    for (const [text, rank] of Object.entries(this.specialTokens)) {
      this.inverseSpecialTokens[rank] = textEncoder.encode(text);
    }
  }

  /**
   * Add to FIFO cache. Callers only add keys that just missed the cache, so
   * every key appears in the ring once and the ring's oldest key is always
   * the oldest live key.
   */
  private addToMergeCache(key: string, value: number[]): void {
    const keys = this.mergeCacheKeys;
    if (this.mergeCache.size >= this.mergeCacheSize && keys.length > 0) {
      // Full: the slot at head holds the oldest live key.
      const head = this.mergeCacheHead;
      this.mergeCache.delete(keys[head]!);
      keys[head] = key;
      this.mergeCacheHead = (head + 1) % keys.length;
    } else {
      keys.push(key);
    }
    this.mergeCache.set(key, value);
  }

  /**
   * Encode a string piece using BPE with caching
   */
  private bytePairEncode(input: string): number[] {
    // Check cache first (no LRU update on access for speed)
    const cached = this.mergeCache.get(input);
    if (cached !== undefined) {
      return cached;
    }

    // BPE encode (direct string lookup already done in calling loop)
    const bytes = textEncoder.encode(input);
    const result = bytePairMerge(
      bytes,
      this.stringRankEncoder,
      this.binaryFirstByteIndex
    );

    // Cache result
    this.addToMergeCache(input, result);

    return result;
  }

  /**
   * Get encoding name
   */
  get encodingName(): string {
    return this.name;
  }

  /**
   * Encode text to tokens (optimized hot path)
   */
  encode(
    text: string,
    allowedSpecial: Array<string> | "all" = [],
    disallowedSpecial: Array<string> | "all" = "all"
  ): number[] {
    // Fast path: no special tokens to handle
    if (!this.hasSpecialTokens || allowedSpecial === "all") {
      return this.encodeOrdinary(text);
    }

    const result: number[] = [];
    const allowedSet = new Set(
      (allowedSpecial as any) === "all" ? this.specialTokenKeys : allowedSpecial
    );

    const disallowedSet = new Set(
      disallowedSpecial === "all"
        ? this.specialTokenKeys.filter((x) => !allowedSet.has(x))
        : disallowedSpecial
    );

    // Check for disallowed special tokens
    if (disallowedSet.size > 0) {
      const disallowedRegex = new RegExp(
        [...disallowedSet].map(escapeRegex).join("|"),
        "g"
      );
      const match = text.match(disallowedRegex);
      if (match) {
        throw new Error(`Text contains disallowed special token: ${match[0]}`);

import Tokenizer from "./tokenizer";
import type { ModelMessage, ToolSet } from "ai";
import type { Model, ModelTokens } from ".";

export interface CountOptions<TOOLS extends ToolSet = ToolSet> {
  /**
   * The tokenizer instance to use for encoding.
   */
  tokenizer: Tokenizer;

  /**
   * Messages from the AI SDK.
   */
  messages: ModelMessage[];

  /**
   * Tools that you'd pass to `streamText` or `generateText`.
   */
  tools?: TOOLS;

  /**
   * The model you wish to use.
   */
  model: Model;
}

export type CountResultMessageContent =
  | {
      type: "text";
      total: number;
    }
  | {
      type: "tool-call";
      total: number;
      input: number;
    }
  | {
      type: "tool-result";
      total: number;
      output: number;
    };

export interface CountResultMessage {
  total: number;
  content: Array<CountResultMessageContent>;
}

export interface CountResultTools<TOOLS extends ToolSet = ToolSet> {
  total: number;
  definitions: Record<
    keyof TOOLS,
    {
      name: number;
      description: number;
      inputSchema: number;
    }
  >;
}

export interface CountResult<TOOLS extends ToolSet = ToolSet> {
  total: number;
  messages: Array<CountResultMessage>;
  tools: CountResultTools<TOOLS>;
}

/**
 * count returns a token estimation for a model given messages and tools.
 *
 * It returns a detailed breakdown per-message and per-tool.
 * Users can filter out messages based on large tool results, for example.
 */
export function count<TOOLS extends ToolSet = ToolSet>(
  options: CountOptions<TOOLS>
): CountResult<TOOLS> {
  const config = options.model.tokens;

  let total = config.baseOverhead;

  // Count messages with detailed breakdown
  const messages: CountResultMessage[] = [];
  for (const message of options.messages) {
    const messageResult = countMessageTokensDetailed(
      options.tokenizer,
      message,
      config
    );
    messages.push(messageResult);
    total += messageResult.total;
  }

  // Count tools with detailed breakdown
  const toolsResult = countToolsTokensDetailed(
    options.tokenizer,
    options.tools,
    config
  );
  total += toolsResult.total;

  return {
    total,
    messages,
    tools: toolsResult as CountResultTools<TOOLS>,
  };
}

/**
 * Count tokens for tools with detailed breakdown
 */
function countToolsTokensDetailed<TOOLS extends ToolSet = ToolSet>(
  tokenizer: Tokenizer,
  tools?: TOOLS,
  config?: ModelTokens
): CountResultTools<TOOLS> {
  if (!config) {
    throw new Error("config is required");
  }

  const definitions: Record<
    keyof TOOLS,
    {
      name: number;
      description: number;
      inputSchema: number;
    }
  > = {} as Record<
    keyof TOOLS,
    {
      name: number;
      description: number;
      inputSchema: number;
    }
  >;
  let total = 0;

  if (tools && Object.keys(tools).length > 0) {
    total += config.toolsExist;

    const toolEntries = Object.entries(tools);
    for (let i = 0; i < toolEntries.length; i++) {
      const [toolName, tool] = toolEntries[i]!;

      // Count name tokens
      const nameTokens = tokenizer.encode(toolName).length;

      // Count description tokens
      let descriptionTokens = 0;
      if (tool.description) {
        descriptionTokens =
          config.perDesc + tokenizer.encode(tool.description).length;
      }

      // Count inputSchema tokens
      let inputSchemaTokens = 0;
      if (tool.inputSchema) {
        const result = countZodSchemaProperties(
          tool.inputSchema,
          tokenizer,
          config
        );
        inputSchemaTokens = result.tokens;
      }

      definitions[toolName as keyof TOOLS] = {
        name: nameTokens,
        description: descriptionTokens,
        inputSchema: inputSchemaTokens,
      };

      total += nameTokens + descriptionTokens + inputSchemaTokens;

      // Add perTool overhead for additional tools (beyond first)
      if (i > 0) {
        total += config.perTool;
      }
    }
  }

  return { total, definitions };
}

/**
 * Count tokens for a single message with detailed breakdown
 */
function countMessageTokensDetailed(
  tokenizer: Tokenizer,
  message: ModelMessage,
  config: ModelTokens
): CountResultMessage {
  let total = config.perMessage;
  const content: CountResultMessageContent[] = [];

  // Count role
  total += tokenizer.encode(message.role).length;

  // Count content with detailed breakdown
  if (message.content) {
    const contentResult = countMessageContentTokensDetailed(
      tokenizer,
      message.content,
      config
    );
    content.push(...contentResult);
    total += contentResult.reduce((sum, c) => sum + c.total, 0);
  }

  return { total, content };
}

/**
 * Count tokens for message content with detailed breakdown
 */
function countMessageContentTokensDetailed(
  tokenizer: Tokenizer,
  content: ModelMessage["content"],
  config: ModelTokens
): CountResultMessageContent[] {
  const multiplier = config.contentMultiplier;
  const results: CountResultMessageContent[] = [];

  if (typeof content === "string") {
    const tokens = tokenizer.encode(content).length;
    const total = Math.round(tokens * multiplier);
    results.push({ type: "text", total });
    return results;
  }

  if (Array.isArray(content)) {
    for (const part of content) {
      if (part.type === "text") {
        const tokens = tokenizer.encode(part.text).length;
        const total = Math.round(tokens * multiplier);
        results.push({ type: "text", total });
      } else if (part.type === "tool-call") {
        let toolCallTokens = 0;
        let inputTokens = 0;

        if (part.toolName) {
          toolCallTokens += tokenizer.encode(part.toolName).length;
        }
