* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --color-bg: #0a0a0a;
  --color-surface: #1a1a1a;
  --color-surface-hover: #222222;
  --color-border: #2a2a2a;
  --color-text: #e5e5e5;
  --color-text-secondary: #a0a0a0;
  --color-primary: #3b82f6;
  --color-primary-hover: #2563eb;
  --color-token-bg: #2a2a2a;
  --color-token-text: #e5e5e5;
  --color-token-border: #3a3a3a;
  --font-mono: 'SF Mono', Monaco, 'Cascadia Code', 'Roboto Mono', Consolas, 'Courier New', monospace;
}

body {
  font-family: var(--font-mono);
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  /* Prevent bounce/overscroll on mobile */
  overscroll-behavior: none;
  /* Improve touch scrolling */
  -webkit-overflow-scrolling: touch;
}

.container {
  max-width: 1400px;
  margin: 0 auto;
  padding: 2rem;
}

header {
  text-align: center;
  margin-bottom: 2rem;
  position: relative;
}

h1 {
  font-size: 2.5rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
  font-family: var(--font-mono);
  background: linear-gradient(135deg, #3b82f6 0%, #8b5cf6 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  letter-spacing: -0.02em;
}

.subtitle {
  color: var(--color-text-secondary);
  font-size: 0.875rem;
  font-family: var(--font-mono);
}

.header-actions {
  margin-top: 1rem;
  display: flex;
  justify-content: center;
  gap: 1rem;
}

.header-link {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: 0.5rem;
  color: var(--color-text);
  text-decoration: none;
  font-size: 0.875rem;
  transition: all 0.2s;
}

.header-link:hover {
  background: var(--color-surface-hover);
  border-color: var(--color-primary);
}

.top-models {
  margin-bottom: 2rem;
  text-align: center;
}

.top-models label {
  display: block;
  margin-bottom: 0.75rem;
  font-size: 0.75rem;
  color: var(--color-text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.model-chips {
  display: flex;
  gap: 0.5rem;
  justify-content: center;
  flex-wrap: wrap;
}

.model-chip {
  padding: 0.5rem 1rem;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: 2rem;
  color: var(--color-text);
  font-size: 0.875rem;
  font-family: var(--font-mono);
  cursor: pointer;
  transition: all 0.2s;
  /* Better touch feedback */
  -webkit-tap-highlight-color: rgba(59, 130, 246, 0.2);
}

.model-chip:hover {
  background: var(--color-surface-hover);
  border-color: var(--color-primary);
}

.model-chip.active {
  background: var(--color-primary);
  border-color: var(--color-primary);
  color: white;
}

.controls {
  display: flex;
  gap: 2rem;
  margin-bottom: 2rem;
  align-items: flex-start;
  flex-wrap: wrap;
}

.control-group {
  flex: 1;
  min-width: 250px;
}

.control-group label {
  display: block;
  margin-bottom: 0.5rem;
  font-weight: 500;
  font-size: 0.875rem;
  color: var(--color-text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

select {
  width: 100%;
  padding: 0.75rem 1rem;
  background: var(--color-surface);
  color: var(--color-text);
  border: 1px solid var(--color-border);
  border-radius: 0.5rem;
  font-size: 0.875rem;
  font-family: var(--font-mono);
  cursor: pointer;
  transition: all 0.2s;
}

select:hover {
  background: var(--color-surface-hover);
  border-color: var(--color-primary);
}

select:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
}

.stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  flex: 1;
}

@media (max-width: 900px) {
  .stats {
    grid-template-columns: repeat(2, 1fr);
  }
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  align-items: flex-start;
}

.stat-label {
  font-size: 0.75rem;
  color: var(--color-text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.stat-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-primary);
  font-family: var(--font-mono);
  min-width: 130px;
  text-align: left;
  font-variant-numeric: tabular-nums;
}

.split-view {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  margin-bottom: 2rem;
}

@media (max-width: 1024px) {
  .split-view {
    grid-template-columns: 1fr;
  }
}

.editor-section,
.output-section {
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.editor-header,
.output-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1rem;
}

.editor-controls {
  display: flex;
  gap: 0.75rem;
  align-items: center;
}

.toggle-control {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.875rem;
  cursor: pointer;
  user-select: none;
}

.toggle-control input[type="checkbox"] {
  cursor: pointer;
}

h2 {
  font-size: 1.25rem;
  font-weight: 600;
}

textarea {
  width: 100%;
  flex: 1;
  min-height: 400px;
  padding: 1rem;
  background: var(--color-surface);
  color: var(--color-text);
  border: 1px solid var(--color-border);
  border-radius: 0.5rem;
  font-size: 0.875rem;
  font-family: var(--font-mono);
  line-height: 1.6;
  resize: none;
  transition: none;
  will-change: contents;
  letter-spacing: normal;
}

textarea:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
}

textarea::placeholder {
  color: var(--color-text-secondary);
}

.btn-secondary {
  padding: 0.5rem 1rem;
  background: var(--color-surface);
  color: var(--color-text);
  border: 1px solid var(--color-border);
  border-radius: 0.375rem;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
  /* Better touch feedback */
  -webkit-tap-highlight-color: rgba(59, 130, 246, 0.2);
}

